T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "아직 길드 밖 플레이어가 없어요.\n같이 파티했던 사람이 자동으로 여기에 추가돼요."
T["Noch keine Positionen."] = "아직 위치가 없어요."
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "아직 점수가 없어요.\n임원이 공격대를 시작하면 참여한 모두에게 참여 점수가 주어져요."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "아직 알려진 레시피가 없어요.\n전문기술 창을 한 번 열어보세요 - 오아시스가 자동으로 길드에 공유해요."
