T["Noch keine Umfragen."] = "아직 설문이 없어요."
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "아직 알려진 게 없어요 - 오아시스를 쓰는 누군가가 이 던전 퀘스트를 가지면 여기 표시돼요."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "아직 비어 있어요. 모닥불 옆에 앉아서\n개요의 '+'로 버프를 목록에 추가해보세요."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "아직 비어 있어요. 모닥불 옆에 앉아서\n오른쪽의 '+'로 버프를 목록에 추가해보세요."
