T["Noch niemand bekannt. Wer das Rezept hat, teilt es automatisch beim Oeffnen des Berufsfensters."] = "아직 알려진 사람이 없어요. 레시피를 가진 사람이 전문기술 창을 열면 자동으로 공유돼요."
