T["Deine Gruesse"] = "내 인사"
T["Deine Grundfarbe + Akzentfarbe"] = "기본 색상 + 강조 색상"
T["Deine Gruppe sucht hier %d Items"] = "파티가 여기서 아이템 %d개를 찾아요"
T["Deine Meldung ist unterwegs zum Entwickler."] = "신고가 개발자에게 전송 중이에요."
T["Deine Oasis-Kontakte"] = "내 Oasis 연락처"
T["Deine Regeln"] = "내 규칙"
T["Deine Rekorde"] = "내 기록"
T["Deine Reservierung"] = "내 예약"
T["Deine Rolle"] = "내 역할"
T["Deine Suche"] = "내 모집"
T["Deine Teile - wem helfen sie?"] = "내 부품 - 누구에게 도움이 될까?"
T["Deine Teile helfen"] = "내 부품이 도움 돼요"
T["Deine Vitrine"] = "내 진열장"
T["Deine Waffen"] = "내 무기"
T["Deine Woche"] = "나의 한 주"
T["Deine handelbaren Teile - wem helfen sie?"] = "거래 가능한 내 부품 - 누구에게 도움이 될까?"
T["Demo ansehen"] = "데모 보기"
T["Demo-Daten gibt es nur in der Entwicklerversion."] = "데모 데이터는 개발자 버전에만 있어요."
T["Demo: Auftrag wuerde gesendet."] = "데모: 의뢰가 전송될 거예요."
T["Demo: Beispielpreise, nur bei dir sichtbar"] = "데모: 예시 가격, 나에게만 보임"
T["Demo: Quest wuerde geteilt."] = "데모: 퀘스트가 공유될 거예요."
T["Demo: spielt einen Ready-Check mit der Beispielgruppe durch."] = "데모: 예시 파티로 전투 준비 확인을 진행해요."
T["Demo: wuerde %s Bescheid sagen."] = "데모: %s에게 알릴 거예요."
T["Demo: wuerde %s anfluestern."] = "데모: %s에게 귓속말할 거예요."
T["Demo: wuerde %s einladen."] = "데모: %s 초대할 거예요."
T["Den Download findest du in unserem Discord."] = "다운로드는 Discord에 있어요."
T["Den Knopf kannst du auch direkt an der Minimap mit der Maus verschieben."] = "버튼은 미니맵에서 마우스로 직접 옮길 수도 있어요."
T["Den Raid-Simulator gibt es nur in der Entwicklerversion."] = "공격대 시뮬레이터는 개발자 버전에만 있어요."
T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "공격대 계획은 길드 관리자, 공대장, 부공대장이 편집할 수 있어요."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "이 직업의 특성 트리는 여기서 표시할 수 없어요. 아래 내보내기 텍스트를 복사하세요."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "%s 님과의 전체 기록을 삭제할까요? 저장한 메시지도 사라져요."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "이 제조법을 가진 모든 제작자에게 의뢰가 가요 - 시간 되는 사람이 수락해요."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "모두에게서 의뢰가 철회돼요."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "의뢰자에게 완료를 알려요."
T["Der Auftraggeber bekommt Bescheid."] = "의뢰자에게 알려요."
T["Der Basar ist leer"] = "바자가 비어 있어요"
T["Der Brachland-Chat mit seinen Spruechen"] = "명언이 가득한 불모의 땅 채팅"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "지금 클라이언트가 숙련도를 주지 않아요 - 접속 후 잠시 기다리세요."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "던전 나침반: 맞는 던전과 거기서 드롭되는 내 아이템."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "적은 앞이 아니라 뒤에 있었어요. 내내."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "파티장이 부공대장으로 지정할 수 있어요."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "전투가 잠겨 있다가 나중에 분석됐어요."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "버튼이 더 이상 마우스로 이동되지 않아요"
T["Der Link gilt fuer alle Leitungen."] = "링크는 모든 담당자에게 적용돼요."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "시장은 경매장 애드온 Midas의 가격을 써요. 나나 길드원이 Midas로 경매장을 검색하면 이 페이지가 열려요."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "플레이 시간 기록이 꺼져 있어요. 켜면 Oasis가 매일 저녁 배워요."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "Oasis 등급은 Oasis의 길드 등급이에요 - 함께 플레이, 도움, 제작, 일정, 휘장으로 올라가요."
T["Der Online-Sound dieser Person ist bei dir aus."] = "이 사람의 접속 효과음이 꺼져 있어요."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "Oasis 창 테두리가 내 색으로 빛나요"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "고리는 남은 점수가 없는 사람을 보여 줘요."
T["Der Steinfresser"] = "돌먹이"
T["Der Termin liegt in der Vergangenheit."] = "일정이 과거예요."
T["Details"] = "상세"
T["Di"] = "화"
T["Diagnose und Abgleich"] = "진단 및 동기화"
T["Diamant"] = "다이아몬드"
T["Diamant = Verbannen (Hexenmeister)"] = "다이아몬드 = 추방 (흑마법사)"
T["Die Bank besucht. Mal kurz nachzaehlen."] = "은행 방문. 한번 세어 볼까요."
T["Die Bannliste ist leer."] = "차단 목록이 비어 있어요."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "Oasis가 대화 입력을 건드린 후 (예: '귓속말' 버튼) /target 입력됨."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "Oasis가 대화 입력을 건드린 후 (예: '귓속말' 버튼) /cast 명령 입력됨."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "Oasis가 대화 입력을 건드린 후 /focus 입력됨."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "Oasis가 대화 입력을 건드린 후 주문 명령 입력됨."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "던전 지도에는 좌표가 없어요. 여기를 클릭한 뒤 지도에서 지금 서 있는 곳을 클릭하세요. 멀리 떨어진 두 곳에서 하면 Oasis가 나와 파티를 지도에 표시해요 - 길드 전체에."
T["Die Gilde bekommt Bescheid"] = "길드에 알림"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "길드가 내가 누구에게 답하는지 봐요. 기본값: 꺼짐"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "길드가 내 불을 %d분간 지도에서 봐요."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "길드가 연대기에서 내 달성을 봐요"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "길드가 지금 이 던전에서 찾는 것이 없어요."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "길드가 아직 전리품 점수를 주지 않아요 - 공격대 관리자가 공격대를 시작하면 값이 나와요."
T["Die Gildenbank wurde noch nicht gelesen"] = "길드 은행을 아직 읽지 않음"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "길드 관리자는 왕관 > 모듈 > 공격대 & 전리품에서 공대장과 부공대장을 지정해요 (이름 또는 길드 등급 기준). 진행 중인 공격대에서는 공대장과 부공대장도 포함돼요."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "길드 관리자는 왕관 > 모듈 > 공격대 & 전리품에서 공대장을 지정해요. 진행 중인 공격대에서는 공대장과 부공대장도 포함돼요."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "길드 관리자는 왕관 > 모듈 > 공격대 & 전리품에서 공대장을 지정해요. 진행 중인 공격대에서는 공대장도 포함돼요."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "길드 관리자가 파티 찾기를 더 높은 등급부터 허용해요."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "길드 관리자가 투표를 더 높은 등급부터 허용해요."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "길드 관리자가 동료 찾기를 껐어요."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "길드 관리자가 공개 초대를 껐어요 - 직접 도전하세요."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "길드 관리자가 왕관 > 모듈에서 허용 등급을 정해요."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "WoW 길드 찾기가 도와줘요 - 중립적, 광고 없음."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "한도는 길드장만 정해요. 등급 1 = 길드장."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "버튼은 대화 입력줄에 명령을 써요 - Enter를 눌러야 실행돼요."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "단축키는 WoW 단축키 설정의 AddOns > Oasis에도 있어요. Esc로 Oasis 창이 닫혀요 (전투 중 제외 - Esc는 게임 몫)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "단축키는 WoW 단축키 설정의 AddOns > Oasis에도 있어요. 마지막으로 창을 클릭했다면 Esc로 Oasis 창이 닫혀요."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "막대가 위로 말려 올라가요; 마우스를 위쪽 가장자리로 가져가면 내려와요 (위에 고정됐을 때만)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "예약 줄은 파티나 공격대에 있을 때만 나타나요"
T["Die Waechter der Sande"] = "모래의 감시자"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "세계 지도를 열었어요. 북쪽이 어디였더라?"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "위쪽 실제 막대에 모든 변경이 바로 표시돼요"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "처음 체력 20은 각 1, 이후 1점당 생명력 10."
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "길드 최다 유령 달리기. 묘지에 내 이름의 벤치가 있어요."
T["Die meisten Screenshots der Gilde"] = "길드 최다 스크린샷"
T["Die meisten Tode der letzten 7 Tage"] = "최근 7일 최다 사망"
T["Die meisten vollen Taschen der Gilde"] = "길드 최다 가방 가득 참"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "최신 공지는 개요 맨 위에 3일간 있어요."
T["Die vergessenen Teiche"] = "잊혀진 연못"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "프로필 카드에 이 휘장이 먼저 보여요 - 나와 길드 모두에게."
T["Diese Hinweise ausschalten"] = "이 알림 끄기"
T["Diese Quest hat %s, nicht du."] = "이 퀘스트는 %s 님 것이에요, 내 것이 아니에요."
T["Diese Quest ist nicht in deinem Questlog."] = "이 퀘스트는 퀘스트 목록에 없어요."
T["Diese Regel gibt es schon."] = "이미 있는 규칙이에요."
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "이 페이지들은 접힌 Oasis 막대의 작은 버튼으로 있어요 - 클릭하면 바로 열려요."
T["Diese Sitzung: %d EP in %s"] = "이번 세션: %d 경험치 (%s)"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "이 언어는 다음 /reload 후 적용 - 여기를 클릭해 다시 불러오기."
T["Diese Taktik ist noch leer."] = "이 전술은 아직 비어 있어요."
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "이번 주는 아직 모두 미완료 - 누가 먼저 시작할까요?"
T["Diese Woche:"] = "이번 주:"
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "이 클라이언트에는 수집 인터페이스가 없어요. /oa probe sammlung 에서 상세 확인."
T["Dieser Client liefert keine Rufdaten - du siehst nur die Staende der anderen."] = "이 클라이언트는 평판 데이터를 주지 않아요 - 다른 사람의 현황만 보여요."
T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "이 클라이언트는 희귀 몹을 알려 주지 않아요 (인터페이스 없음). /oa probe rares 에서 상세 확인."
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "길드에 있는 것 중 부족한 게 없어요 - 대단해요!"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "자신에게 귓속말했어요. 누가 이렇게 잘 들어 줄까요?"
T["Discord-Bruecke: Ist sie an, speichert WoW den ganzen Chat (auch Fluestern) im Klartext in Logs/WoWChatLog.txt."] = "Discord 연결: 켜면 WoW가 모든 대화(귓속말 포함)를 Logs/WoWChatLog.txt에 평문으로 저장해요."
T["Discord-Link"] = "Discord 링크"
T["Discord-Link - z.B. discord.gg/deinegilde (Enter speichert)"] = "Discord 링크 - 예: discord.gg/deinegilde (Enter로 저장)"
T["Discord-Nachrichten im Gildenchat zeigen (ueber OasisSync, nach /reload)"] = "길드 대화에 Discord 메시지 표시 (OasisSync 사용, /reload 후)"
T["Discord-Nachrichten uebernommen: %d (neue erscheinen erst nach /reload)"] = "Discord 메시지 가져옴: %d (새 메시지는 /reload 후 표시)"
T["Diskoball"] = "디스코볼"
T["Distanz"] = "거리"
T["Distanz-Angriffskraft"] = "원거리 전투력"
T["Disziplin"] = "수양"
T["Do"] = "목"
T["Dock"] = "도킹"
T["Dolche"] = "단검"
T["Doppelte Oasis-XP ab %s fuer %d Stunden!"] = "%s부터 %d시간 동안 Oasis 경험치 2배!"
T["Doppelte Oasis-XP fuer alle in der Gilde. Alle mit Oasis bekommen eine Durchsage."] = "길드 모두에게 Oasis 경험치 2배. Oasis 사용자 모두 공지를 받아요."
T["Doppelter Rechtsklick wirft aus, Fang-Statistik in der Uebersicht"] = "오른쪽 더블 클릭으로 낚시, 낚시 통계는 개요에"
T["Doppelter Rechtsklick wirft die Angel aus (Angel muss angelegt sein)."] = "오른쪽 더블 클릭으로 낚시 (낚싯대 착용 필요)."
T["Double XP"] = "경험치 2배"
T["Double XP laeuft"] = "경험치 2배 진행 중"
T["Download in unserem Discord: %s"] = "Discord에서 다운로드: %s"
T["Drachenfeueramulett"] = "용의 불꽃 목걸이"
T["Dreieck"] = "세모"
T["Dreieck = Kopfnuss (Schurke)"] = "세모 = 혼절시키기 (도적)"
T["Dschungel"] = "정글"
