T["Noch keine Beute erfasst"] = "아직 기록된 전리품 없음"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "아직 지원자 없음. 위에 이름 입력 - 상태 클릭으로 다음 단계."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "아직 데이터 없음 - Oasis 사용자의 다음 동기화 때 장비가 와요."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "아직 데이터 없음 - 길드원이 15분마다 측정을 보내요 (이 버전부터)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "아직 데이터 없음 - 수집품 창을 한 번 열거나 탈것과 애완동물을 가방에 넣으세요. Oasis 사용 길드원이 접속하면 여기 나와요."
T["Noch keine Daten von der Gilde."] = "아직 길드 데이터 없음."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "아직 데이터 없음. Oasis 사용 길드원이 접속하면 공격대 귀속이 여기 나와요."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "아직 기록된 던전 진행 없음."
T["Noch keine Dungeons geplant."] = "아직 계획된 던전 없음."
T["Noch keine Eintraege."] = "아직 항목 없음."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "아직 사용한 이모지 없음 - 이모지 선택의 즐겨찾기가 여기 나와요."
T["Noch keine Favoriten - Diamant anklicken."] = "아직 즐겨찾기 없음 - 다이아몬드를 클릭하세요."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "아직 즐겨찾기 없음 - 별표 또는 효과음 오른쪽 클릭."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "아직 즐겨찾기 없음.\n이모지를 오른쪽 클릭하면 여기 저장돼요."
T["Noch keine Fluesternachrichten."] = "아직 귓속말 없음."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "아직 귓속말 없음. 길드원에게 써 보세요!"
T["Noch keine Fraktionen entdeckt."] = "아직 발견한 진영 없음."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "아직 길드 목표 없음. 첫 목표를 만드세요 - 예: 전설 무기나 공격대 재료."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "아직 전투 보고서 없음. 첫 보스전 후 모든 시도가 여기 나와요 - 사망 타임라인과 반복 패턴 포함."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "아직 전투 보고서 없음. 첫 보스전 후 모든 시도가 여기 나와요."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "아직 후보 없음. 길드 밖 사람과 플레이하세요 - 길드 없고 평가 좋은 사람이 여기 나와요."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "아직 조합 없음.\nShift+클릭으로 이모지 여러 개 선택 후 저장."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "아직 연락처 없음. 다른 Oasis 사용자와 파티를 하면 길드가 없어도 여기 기억돼요."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "아직 이정표 없음. 레벨 업하고 전문 기술을 배우세요 - 여기서 내 이야기가 시작돼요."
T["Noch keine Meldungen aus der Gilde."] = "아직 길드 알림 없음."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "아직 순간 없음 - 그냥 플레이하면 Oasis가 기록해요."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "관리자 대화에 아직 메시지 없음. 지금부터 /o 채널에 쓰는 모든 것이 여기 나와요."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "아직 위치 없음 - Oasis 사용 길드원이 돌아다니면 지도가 채워져요."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "아직 가격 없음. Midas로 경매장을 검색하면 여기 나와요."
T["Noch keine Profile gespeichert."] = "아직 저장된 프로필 없음."
T["Noch keine Punkte"] = "아직 점수 없음"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "아직 기록된 공격대 날 없음. 공대장(Oasis 사용)이 보스 처치마다 자동 기록해요."
T["Noch keine Regeln"] = "아직 규칙 없음"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "아직 규칙 없음. 빠른 템플릿을 쓰거나 위에서 직접 만드세요."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "아직 평판 데이터 없음. Oasis 사용 길드원이 접속하면 자동으로 와요."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "아직 공유된 수집품 없음. Oasis 사용 길드원이 접속하면 여기 나와요."
T["Noch keine Sets."] = "아직 세트 없음."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "아직 발견 없음. Oasis 사용자가 희귀 몹을 보면 여기 나와요."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "아직 알려진 플레이 시간 없음. 접속하는 저녁마다 Oasis가 배우고 다른 사람의 프로필도 가져와요."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "아직 검색 없음. 레벨 입력 후 \"검색\" 클릭 - 길드 있는 플레이어는 숨겨져요."
T["Noch keine Taktiken."] = "아직 전술 없음."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "아직 전술 없음. 공격대 관리자가 보스마다 짧은 전술을 만들 수 있어요 - 모두 여기서 보고 대상 지정 시 표시돼요."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "아직 알려진 특성 없음. Oasis 사용 길드원은 자동 공유; 다른 플레이어: 대상 지정 후 살펴보기 (오른쪽 클릭 > 살펴보기) 또는 대상을 잡고 여기를 다시 열기."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "아직 분배 없음 - 공격대 관리자가 전리품을 나누면 여기 나와요."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "아직 값 없음 - 다음 전투 후 누가 앞서는지 여기 나와요."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "아직 희망 날짜 없음 - 가능한 날을 누르세요."
T["Noch keine Wunschtage gemeldet."] = "아직 신청된 희망 날짜 없음."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "아직 목표 없음. 위에서 만드세요 - Oasis가 자동으로 체크해요."
T["Noch keine Zusagen - sei der Erste!"] = "아직 수락 없음 - 첫 번째가 되세요!"
T["Noch keine eigene Beute"] = "아직 내 전리품 없음"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "아직 기록된 내 전리품 없음 ('희귀' 품질부터, 설정 가능)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "아직 신청 안 함 - 아래에서 역할을 선택하세요"
T["Noch nicht bereit"] = "아직 준비 안 됨"
T["Noch nicht fuer die Gilde uebernommen:"] = "아직 길드에 적용 안 됨:"
T["Noch nicht kalibriert - Kalibrieren?"] = "아직 보정 안 됨 - 보정할까요?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "위시리스트가 비어 있어요.\n필요한 것을 위에 입력하세요 - Oasis 사용자 모두 툴팁과 획득 시 봐요."
T["Noch nichts aufgezeichnet."] = "아직 기록된 것 없음."
T["Noch nichts benutzt."] = "아직 사용한 것 없음."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "아직 차단된 것 없음. WoW가 Oasis를 차단하면 어떤 기능인지, 직전에 Oasis가 무엇을 했는지 여기 나와요."
T["Noch nichts eingelesen"] = "아직 읽은 것 없음"
T["Noch nichts geangelt."] = "아직 낚은 것 없음."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "아직 저장한 것 없음 - 메시지 오른쪽 클릭: 메시지 저장."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "아직 아무 일도 없어요 - 떠나서 역사를 쓰세요!"
T["Noch nichts reserviert"] = "아직 예약 없음"
T["Noch nichts reserviert - ein Item pro Termin."] = "아직 예약 없음 - 일정당 아이템 하나."
T["Noch nichts reserviert."] = "아직 예약 없음."
T["Noch nichts verkauft."] = "아직 판매 없음."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "아직 분배 없음. 규칙이 적용되면 여기 나와요."
T["Noch nie direkt mit dir abgeglichen"] = "아직 나와 직접 동기화한 적 없음"
T["Noch niemand angefluestert."] = "아직 귓속말한 사람 없음."
T["Noch niemand aus der Gilde hat es uebrig."] = "아직 여분이 있는 길드원이 없어요."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "내 전문화의 길드원 중 특성을 공유한 사람이 없어요 (Oasis 사용자는 자동 공유)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Oasis 기록 이후 떠난 사람 없음."
T["Noch niemand gemeldet - sei der Erste!"] = "아직 신청자 없음 - 첫 번째가 되세요!"
T["Noch niemand sonst kennt das Rezept."] = "아직 이 제조법을 아는 사람이 없어요."
T["Noch niemand teilt seine Handelsbilanz."] = "아직 거래 결산을 공유한 사람이 없어요."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "아직 거래 결산을 공유한 사람이 없어요. 아래 '결산 공유'를 켜면 시작돼요."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "아직 Oasis로 거래 가능 부품을 공유한 사람이 없어요. Oasis 사용 길드원이 많을수록 여기가 채워져요."
T["Noch zu uebergeben"] = "아직 전달할 것"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "최다 접속 시간을 정하기엔 데이터 부족"
T["Normal"] = "일반"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "보통 Oasis는 내가 아직 열어 둔 모집만 알려요"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "메모 (직업, 연락처, 인상 ...)"
T["Notiz an den Plundermeister (optional)"] = "전리품 담당자에게 메모 (선택)"
T["Notiz der Gildenleitung"] = "길드 관리자 메모"
T["Notiz von %s: %s"] = "%s 님의 메모: %s"
T["Notiz zu %s"] = "%s 메모"
T["Notiz zur Person"] = "사람 메모"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "모집 메모 (시간, 만남 장소) ..."
T["Notizen sehen und schreiben nur Offiziere."] = "메모는 관리자만 보고 쓸 수 있어요."
T["Nur %s"] = "%s만"
T["Nur Abende vorschlagen"] = "저녁만 제안"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "배너와 세 열만 (접속자, 소식, 다음 일정) - 타일과 하이라이트 줄 없음"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "착용 장비보다 좋은 전리품이 있는 던전만."
T["Nur Eintraege dieser Person"] = "이 사람의 항목만"
T["Nur Farbverlauf"] = "그라데이션만"
T["Nur Gegner im Kampf"] = "전투 중인 적만"
T["Nur Gildenleitung"] = "길드 관리자만"
T["Nur Gruppenquests beruecksichtigen"] = "파티 퀘스트만 고려"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "내 지역 모닥불만 알림"
T["Nur Mains ab Level"] = "최소 레벨 이상 본캐만"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "이 등급까지만 파티 찾기 시작 가능 (10 = 모두)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "이 등급까지만 새 투표 시작 가능 (10 = 모두)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Oasis 사용 길드원만. 미완료 퀘스트 아이템, 남는 퀘스트 아이템, 공유 가능 퀘스트를 공유해요."
T["Nur Oasis-Spieler"] = "Oasis 사용자만"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Oasis 사용자만: 각자 자기 언어로 봐요."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "관리자와 길드 관리자만 이 채널(/o)을 봐요."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "전리품 담당자, 공대장, 부공대장만 분배할 수 있어요."
T["Nur Rezepte, die du selbst kannst"] = "내가 할 수 있는 제조법만"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "지금 접속자가 제작 가능한 제조법만"
T["Nur Upgrades"] = "업그레이드만"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "내 파티에만, 던전 지도용"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "보기만 - 편집: 관리자, 공대장, 부공대장"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "보기만 - 그리기는 공대장만"
T["Nur auf diesem PC"] = "이 PC에만"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "숨김만 - 여기를 클릭해 돌아가기."
T["Nur bei dir"] = "나만"
T["Nur bei dir gespeichert"] = "나에게만 저장"
T["Nur bei gleicher Klasse und Spezialisierung."] = "같은 직업과 전문화일 때만."
T["Nur das Noetigste"] = "꼭 필요한 것만"
T["Nur der Gildenmeister kann das aendern."] = "길드장만 변경할 수 있어요."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "길드장만, 최대 10개 등급."
T["Nur der Gruppenleiter kann eine Suche starten."] = "파티장만 모집을 시작할 수 있어요."
T["Nur der Gruppenleiter kann suchen"] = "파티장만 검색 가능"
T["Nur die Gildenleitung kann das aendern."] = "길드 관리자만 변경할 수 있어요."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "길드 관리자만 데스롤 순위를 초기화할 수 있어요."
T["Nur die wichtigsten Bereiche sind an."] = "가장 중요한 구역만 켜져 있어요."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "이 사람만 들어요 (Oasis가 있으면)."
T["Nur diesen Abschnitt posten"] = "이 구역만 게시"
T["Nur fehlende"] = "부족한 것만"
T["Nur fuer Anfuehrer und Assistenten"] = "공대장과 부공대장 전용"
T["Nur fuer Offiziere"] = "관리자 전용"
T["Nur fuer Schlachtzugsleiter"] = "공대장 전용"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "공대장 & 부공대장 전용"
