T["Weltkarte aufdecken"] = "세계 지도 밝히기"
T["Weltkarte aufdecken findest du unter Bereiche > Karte."] = "세계 지도 밝히기는 구역 > 지도에 있어요."
T["Weltkarte aufdecken findest du unter der Weltkarte und unter Bereiche > Karte."] = "세계 지도 밝히기는 세계 지도 아래와 구역 > 지도에 있어요."
T["Wen moechtest du herausfordern? Namen eingeben oder jemanden anvisieren."] = "누구에게 도전할까요? 이름을 입력하거나 대상을 잡으세요."
T["Wenn jemand etwas bei dir oder deinem Beruf bestellt (und wenn dein Auftrag fertig ist)"] = "누군가 나나 내 전문 기술에 주문할 때 (그리고 내 의뢰가 완료될 때)"
T["Wenn jemand online kommt"] = "누군가 접속할 때"
T["Wer"] = "누구"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "다른 사람에게 거부되는 데이터를 보내는 사람 (권한 없음, 위조된 작성자, 꾸며낸 항목). 수정하지 않은 Oasis는 거의 그러지 않아요 - 증거가 아닌 단서."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "관심을 표시한 사람이 여기 맞는 자리에 나와요. 일정이 있으면 카드에서 바로 신청하세요."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "위시리스트에 이 아이템이 있는 길드원"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "메뉴에서 이 구역을 보는 사람 (길드 관리자는 항상 모두 봐요)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "길드를 떠났거나 추방된 사람. 누가 돌아오면 Oasis가 길드 관리자에게 알려요."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "위쪽 왕관을 보는 사람. 권한이 없으면 회색이고 미리보기만 열려요."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "길드 대화 위에 메시지를 고정할 수 있는 사람"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "초대 권한자를 아직 몰라요 - 본캐로 한 번 접속하면 Oasis가 길드 관리자를 기억해요."
T["Wer geht mit nach %s? Ich suche %s"] = "%s 같이 갈 분? %s 구해요"
T["Wer hat ...?"] = "누가 ... 가졌나요?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "내가 필요한 퀘스트 아이템은 누가? 내가 도울 사람은?"
T["Wer hat was bekommen"] = "누가 무엇을 받았나"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "공격대에서 점수(참여/전리품)를 기록할 수 있는 사람."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "파티나 공격대에서 누가 어떤 버프가 있고 무엇이 부족한지"
T["Wer ist bereit? Ampeln je Spieler"] = "누가 준비됐나? 플레이어별 신호등"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "이번 주 누가 귀속됐고, 누가 비어 있고 해금됐나 - 본캐와 부캐"
T["Wer ist online"] = "접속자"
T["Wer ist online?"] = "접속자?"
T["Wer ist wann online"] = "누가 언제 접속하나"
T["Wer ist wie weit"] = "누가 얼마나 진행했나"
T["Wer kann was herstellen, Markt, Gildenbank"] = "누가 무엇을 제작하나, 시장, 길드 은행"
T["Wer koennte mit: %s"] = "같이 갈 만한 사람: %s"
T["Wer koennte mit?"] = "같이 갈 만한 사람?"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "자주 참가하고 적게 받은 사람이 '입찰'에서 우선이에요. 매주 점수 일부가 소멸해요."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "맞는 역할로 신청한 사람은 바로 파티에 초대돼요."
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "누가 어느 진영에서 어디쯤? 목표 직전, 함께 파밍, 이번 주 진행"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "누가 가장 많이 때리고, 치유하고, 맞나?"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "길드 관리자는 길드장이 왕관 > 길드에서 정해요."
T["Werbung"] = "홍보"
T["Werte"] = "능력치"
T["Werte bringen deiner Rolle nichts"] = "능력치가 내 역할에 쓸모없음"
T["Werte nur zur Info"] = "능력치는 참고용"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "내 캐릭터의 능력치, 연감, 일일 목표, 기록, 모험."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "능력치: +치유, 지능, 정신력, 마나 회복;무기: 지팡이 또는 한손 무기 + 치유 보조장비;치유: 회복과 재생 미리, 큰 피해엔 치유의 손길;팁: 마나엔 정신 자극, 쓰러진 치유사엔 환생"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "능력치: +치유, 지능, 주문 치명타 (깨달음이 마나 반환), 마나 회복;무기: 한손 무기 + 치유 보조장비/방패;치유: 작은 피해엔 빛의 섬광, 큰 피해엔 성스러운 빛 (낮은 등급);팁: 축복 배분, 끌려가면 신의 보호"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "능력치: +치유, 마나 회복 (MP5), 지능 - 정신력은 효과 적음;무기: 한손 무기 + 치유 방패;치유: 파티엔 연쇄 치유, 방어엔 치유의 물결 (낮은 등급);팁: 마나 샘 토템 설치, 방어에게 대지의 보호막"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "능력치: +치유, 정신력 (명상: 시전 중에도 회복), 지능, 마나 회복;무기: 지팡이 또는 한손 무기 + 치유 보조장비, 마법봉;치유: 소생과 신의 권능: 보호막 미리, 방어엔 상급 치유 (낮은 등급);팁: 파티엔 치유의 기원, 어그로엔 소실"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "능력치: 방어도 (곰 변신이 배로 늘림), 체력, 민첩성 (회피 + 방어도);무기: 피해와 무관 - 능력치만 중요 (체력 붙은 지팡이/장창);순환: 할퀴기, 파티엔 휘둘러치기, 위협의 포효;팁: 위협 수준엔 힘, 시작에 격노"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "능력치: 힘 (1점 = 전투력 2), 민첩성 (전투력 + 치명타), 치명타, 적중 +9 %까지;무기: 피해와 무관 - 능력치만 중요;순환: 할퀴기/칼날 발톱으로 연계 점수, 그다음 흉포한 이빨;팁: 기력엔 변신 재시전, 은신에서 기습"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "능력치: 힘 (1점 = 전투력 2), 치명타 (질풍 발동 = 빠른 공격), 적중 +9 %까지;무기: 느린 양손 무기 - 질풍은 타격마다 발동, 느릴수록 피해 증가;순환: 질풍의 무기, 폭풍의 일격, 대지 충격;팁: 파티에 대지력 토템과 질풍의 토템"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "능력치: 힘 (1점 = 전투력 2), 치명타, 적중 +9 %까지;무기: 느린 양손 무기 - 문장과 심판은 타격마다;순환: 정의/지휘의 문장, 심판, 문장 다시 걸기;팁: 신성화는 마나 충분할 때만, 자신에겐 힘의 축복"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "능력치: 적중 +9 %까지, 민첩성 (전투력 1, 약 29 = 치명타 1 %), 전투력, 치명타;무기: 전투 = 빠른 보조장비, 느린 주무기 (사악한 일격); 기습엔 단검;순환: 연계 점수 쌓기, 난도질 유지, 그다음 절개;팁: 쌍수는 일반 공격이 더 자주 빗나가요 - 적중이 가장 중요"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "능력치: 적중 +9 %까지, 민첩성 (원거리 전투력 2, 약 53 = 치명타 1 %), 전투력, 지능;무기: 느린 원거리 무기 (발사당 높은 피해), 능력치 붙은 근접 무기;순환: 사냥꾼의 징표, 자동 사격, 사이사이 조준 사격/일제 사격;팁: 동반자는 먹여서 기분 좋게, 얼음의 덫(네모)로 제어"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "능력치: 적중 +9 %까지, 힘 (1점 = 전투력 2), 치명타 (민첩성 약 20 = 1 %);무기: 느린 양손 무기 (필사의 일격, 영웅의 일격은 타격마다);순환: 분노 쌓기, 필사의 일격 / 피의 갈증, 소용돌이, 남는 분노는 영웅의 일격;팁: 전투 전 전투의 외침, 생명력 20 % 미만엔 마무리 일격"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "능력치: 방어 (440 = 60레벨 보스 상대 치명타 면역), 체력, 방어도, 방패 막기;무기: 한손 무기 + 방패, 빠른 무기 = 분노 증가;순환: 방패 가격/복수, 대상에 방어구 가르기, 분노 많으면 영웅의 일격;팁: 적중은 도발과 기술이 빗나가지 않게 도와요"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "능력치: 방어, 체력, 방어도, 그다음 위협 수준용 주문 피해;무기: 한손 무기 (주문 피해 붙으면 좋음) + 방패;순환: 정의의 격노 켜기, 파티엔 신성화, 신성한 방패 유지;팁: 마나가 부족해요 - 지혜 또는 지능의 문장 챙기기"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "능력치: 주문 피해, 주문 치명타 (정기의 집중이 마나 절약), 지능, 마나 회복;무기: 한손 무기 + 주문 피해 방패/보조장비;순환: 번개 화살 연타, 파티엔 연쇄 번개, 화염 충격;팁: 공격대에선 주문 적중 +16 %까지, 마나 부족엔 마나 샘 토템"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "능력치: 주문 피해, 주문 치명타, 지능, 공격대에선 주문 적중 +16 %까지;무기: 지팡이 또는 한손 무기 + 주문 피해 보조장비;순환: 달빛 섬광 + 곤충 떼, 그다음 천벌 또는 별빛 화살;팁: 마나 부족하면 자신에게 정신 자극"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "능력치: 주문 피해, 주문 적중 +16 %까지 (공격대), 체력, 지능;무기: 지팡이 또는 단검 + 주문 피해 보조장비, 남은 마나엔 마법봉;순환: 부패 + 저주, 그다음 어둠의 화살; 마시기 대신 생명력 전환;팁: 체력은 두 배로 유용 (생명력 전환, 공허방랑자/영혼 연결)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "능력치: 주문 피해, 주문 적중 +16 %까지 (공격대), 마나엔 정신력;무기: 지팡이 또는 한손 무기 + 주문 피해 보조장비;순환: 어둠의 권능: 고통, 정신 분열, 정신의 채찍;팁: 어둠의 형상 상시 유지, 흡혈의 선물이 파티 치유"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "능력치: 주문 피해, 그다음 주문 적중 +16 %까지 (공격대 보스), 지능, 주문 치명타;무기: 주문 피해 지팡이, 남은 마나엔 마법봉;순환: 얼음 화살 또는 화염구 연타, 마나 바닥엔 환기;레벨 업: 지능과 정신력 = 휴식 감소, 파티에선 양(달) 걸기"
