T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "활성: 밈 사운드, 음악, 길드 이모지가 포함돼 있어요."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "임원 등급 아래의 활동 중인 길드원은 같은 등급으로 이 일수가 지나면 '승급' 목록에 표시돼요. 0 = 끔."
T["Aktuelles Gebiet zuerst"] = "현재 지역 먼저"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "모든 영역을 주제별로 묶었어요: 길드, 함께 플레이, 공격대, 거래, 재미. 제목을 클릭하면 묶음이 접혀요."
T["Alle Gebiete aufklappen"] = "모든 지역 펼치기"
T["Alle Gebiete zuklappen"] = "모든 지역 접기"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "모든 길드원의 등급, 레벨, Oasis 버전. 줄을 우클릭: 등급 변경."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "모든 글꼴은 SIL Open Font License 1.1 적용"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: 불타는 아드레날린: 즉시 공격대 밖으로 이동 (곧 죽어요).\nAll: 시작 시 자원 가득 - 전부 쏟아붓기.\nTank: 탱커 순서 정하기 (탱커에게 아드레날린).\nDD: 용의 앞이나 뒤에 서지 않기."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Firesworn 8마리를 공격대 근처에서 죽이지 않기 (폭발).\nTank: 쫄 탱커는 각자 Firesworn을 멀리 끌고 가기, 흑마법사는 추방.\nHealer: 해제, 쫄 탱커 주시.\nDD: 가르 먼저, 쫄은 지시가 있을 때만."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: 심장부 맹수 두 마리는 보스에게서 떨어뜨려 탱킹, 죽이지 않기.\nTank: 용암 튀기기 중첩이 너무 높으면 골레마그 탱커 교대.\nDD: 골레마그만 공격."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: 사제 4마리 먼저, 서로 치유해요.\nTank: 설퍼론과 사제들을 떨어뜨리기.\nDD: 차단! 사제의 암흑의 치유 끊기."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: 화염 저항! Wrath of Ragnaros가 근접을 날려요 - 그 뒤 다시 붙기.\nAll: 피조물 단계 (3분 후 또는 잠수 시): Sons of Flame 모두 처치.\nTank: 첫 탱커가 날아가면 두 번째 탱커 대기.\nHealer: 산개, 원거리는 너무 가까이 가지 않기 (용암 폭발).\nDD: 근접: 마나 관리, 원거리는 거리 유지."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 화염 강타 중첩 - 원거리는 기둥 뒤에서 중첩 해소.\nTank: 탱커 두 명 기둥 뒤, 폭풍 날개가 밀쳐내요.\nDD: 오닉시아 비늘 망토 필수."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: 게헨나스의 저주 (치유량 감소) 즉시 해제.\nAll: 불의 비에서 벗어나기.\nTank: 불꽃지기 두 마리를 떨어뜨려 탱킹.\nDD: 불꽃지기 먼저, 그다음 게헨나스."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: 루시프론의 저주와 파멸의 예언 즉시 해제 (마법사/드루이드, 사제/성기사).\nTank: 경비병 두 마리를 떨어뜨려 탱킹 - 정신 지배!\nHealer: 산개, 정신 지배당한 플레이어 해제.\nDD: 경비병 먼저, 그다음 루시프론."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: 살아있는 폭탄: 즉시 공격대 밖으로 이동!\nAll: 불지옥 - 보스에게서 떨어지기, 마나 점화 해제.\nTank: 중앙 유지, 불지옥 때 잠시 빠지기.\nDD: 근접은 불지옥 때 물러나기."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: 경비병의 마법 반사/피해 보호막 주의 - 그때는 공격 중지.\nTank: 탱커 한 명당 경비병 하나, 마법사는 정예 경비병 변이.\nDD: 치유 경비병 (Flamewaker Healer) 먼저."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: 오닉시아의 앞이나 뒤에 절대 서지 않기 (숨결과 꼬리 휘두르기).\nAll: 2단계 (65%): 화염구 피하기, 동굴 입구에 들어가지 않기.\nAll: 3단계 (40%): 공포 - 공포의 수호물/진동의 토템 준비, 용암 균열 피하기.\nTank: 오닉시아를 벽 쪽에 옆으로, 머리는 공격대 반대로.\nTank: 2단계: 새끼용 모으기. 3단계: 즉시 어그로 되찾기.\nHealer: 탱커 우선, 2단계에는 산개.\nDD: 탱커가 3번 공격할 때까지 대기. 2단계: 새끼용 먼저."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: 공황 - 공포의 수호물/진동의 토템, 사냥꾼: 광기에 평정의 사격.\nAll: 바닥의 용암 불길에서 벗어나기.\nTank: 마그마다르의 등이 공격대를 향하게.\nDD: 원거리는 뒤쪽에 산개."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: 1단계: 양쪽에서 용족 등장, 직업 호출 주의.\nAll: 3단계 (20%): 해골이 다시 일어나요 - 다시 처치.\nTank: 네파리안을 벽 쪽에, 공포 - 공포의 수호물.\nHealer: 사제 직업 호출: 치유가 피해를 줘요 - 주의.\nDD: 사냥꾼/전사: 직업 호출 주의 (무기 파괴, 태세)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: 1단계: 알 파괴 (수정구로 정신 지배), 쫄 잡기.\nAll: 알을 모두 부순 뒤: 보스가 방으로 - 화염 회오리.\nTank: 쫄을 계단에 모으기.\nDD: 마법사와 용족 먼저."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 광기 - 사냥꾼: 평정의 사격.\nTank: 탱커 두 명, 폭풍 날개 주의.\nDD: 오닉시아 비늘 망토 필수."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: 에본로크의 그림자가 보스를 치유해요 - 디버프 걸린 탱커 교대.\nTank: 탱커 두 명이 그림자 때 교대.\nDD: 오닉시아 비늘 망토 필수."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: 밀쳐내기 - 벽에 붙어 서기.\nTank: 탱커 두 명, 날려버리기로 어그로가 나뉘어요.\nDD: 탱커에게 죽음의 일격: 힐러 대비."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: 순간이동해요 - 어그로를 가진 사람은 도망가지 않기.\nAll: 샤즈라의 저주 해제, 신비한 폭발: 근접은 거리 유지.\nTank: 점멸할 때마다 바로 다시 붙기.\nHealer: 해제 (마법 약화)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: 매주 다섯 가지 숨결 중 두 가지 - 숨결은 모퉁이 뒤에서 피하기.\nAll: 청동 고통에는 모래시계 모래.\nTank: 문에서 탱킹, 공격대는 모퉁이 뒤.\nDD: 광기에 평정의 사격."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Alt 누르기: 모든 능력치와 평가 상세. Shift: Blizzard 비교."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Alt 떼기: 간단히 보기. Shift: Blizzard 비교."
T["Altes Oasis"] = "구버전 Oasis"
T["An: mit der Maus an eine eigene Stelle ziehen. Aus: haengt am Talentfenster."] = "켬: 마우스로 원하는 곳에 끌어 놓기. 끔: 특성 창에 붙음."
T["Anfuehrer der Dunkelspeere"] = "검은창 부족의 지도자"
T["Angefangener Text bleibt beim Wechsel des Gespraechs stehen"] = "보내지 않은 글은 대화를 바꿔도 남아 있어요"
T["Animationen aus"] = "애니메이션 끄기"
T["Ansprechpartner"] = "담당자"
T["Anwesenheit und Ausruestung der Gilde im Blick."] = "길드의 출석과 장비를 한눈에."
T["Auf dem Flug nichts erkennen oder melden"] = "비행 중에는 아무것도 감지하거나 알리지 않기"
T["Auf dem Flugmeister-Flug kannst du ohnehin nicht anhalten"] = "어차피 비행 중에는 멈출 수 없어요"
T["Aus FojjiCore (%d)"] = "FojjiCore에서 (%d)"
T["Aus Guides zur Forever-Beta - kann sich noch aendern."] = "Forever 베타 공략 기준 - 아직 바뀔 수 있어요."
T["Aus dem Soundpaket (ruhig)"] = "사운드 팩에서 (차분함)"
