T["Ausklappen"] = "펼치기"
T["Ausloggen: Blizzards Dialogliste war von Oasis beruehrt (ab 0.5.478 behoben - bitte Oasis aktualisieren)."] = "접속 종료: Blizzard의 대화창 목록이 Oasis의 영향을 받았어요 (0.5.478에서 수정 - Oasis를 업데이트해 주세요)."
T["Banner auf der Uebersicht: Midas, das Auktionshaus-Addon von Rebo aus der Gilde OASIS"] = "개요의 배너: 길드 OASIS의 Rebo가 만든 경매장 애드온 Midas"
T["Befoerderung vorschlagen nach"] = "승급 제안 기준"
