T["Beispieldaten gibt es nur in der Entwicklerversion."] = "예시 데이터는 개발자 버전에만 있어요."
T["Bereiche freigeben"] = "영역 켜기"
T["Bereit fuer den Pull? Bereitschaft, Verzauberungen und Buffs je Spieler"] = "풀링 준비됐나요? 플레이어별 준비 상태, 마법부여, 버프"
T["Bestaetigte Crit-Rekorde aus der Logdatei importiert."] = "확인된 치명타 기록을 로그 파일에서 가져왔어요."
T["Beta-Geschenk"] = "베타 선물"
T["Beute automatisch verteilen, wenn du Pluendermeister bist"] = "전리품 담당자일 때 전리품 자동 분배"
T["Beuterat ab Rang"] = "전리품 위원회 최소 등급"
T["Bilder / Sek."] = "프레임 / 초"
T["Bilder ueber 1 ms (seit Sitzungsbeginn): %d"] = "1 ms 초과 프레임 (이번 세션): %d"
T["Bitte den Namen eines Gildenmitglieds eingeben (nicht einen eigenen Charakter)."] = "길드원의 이름을 입력하세요 (내 캐릭터 제외)."
T["Blockiert"] = "차단됨"
T["Blockierung von %s beobachtet; Ausloeser nicht bestaetigt."] = "%s 차단이 감지됐어요. 원인은 확인되지 않았어요."
T["Boss der Defias"] = "데피아즈단의 두목"
T["Boss von Ratschet - alles hat seinen Preis"] = "톱니항의 두목 - 모든 것에는 값이 있다"
T["Boss-Positionen im Dungeon-Atlas und Drop-Chancen der Dungeon-Bosse - GPL-2.0. Autoren: Lag, Daviesh und weitere"] = "던전 지도의 보스 위치와 던전 보스 드롭 확률 - GPL-2.0. 제작: Lag, Daviesh 외"
T["Bosse & Beute"] = "보스 & 전리품"
T["Brutmutter der Schwarzdrachen"] = "검은용군단의 여왕"
T["Building: Auswahl"] = "Building: 선택"
T["Building: Bestaetigen"] = "Building: 확인"
