T["Building: Hinweis"] = "Building: 알림"
T["Building: Klick"] = "Building: 클릭"
T["Building: Schalter"] = "Building: 스위치"
T["Builds aus der Gilde ausgeblendet. Wieder einblenden: /oa builds"] = "길드 빌드를 숨겼어요. 다시 표시: /oa builds"
T["Builds aus der Gilde wird wieder neben dem Talentfenster gezeigt."] = "길드 빌드가 다시 특성 창 옆에 표시돼요."
T["Cairne Bluthuf"] = "케른 블러드후프"
T["Casual: Auswahl"] = "Casual: 선택"
T["Casual: Bestaetigen"] = "Casual: 확인"
T["Casual: Fenster auf"] = "Casual: 창 열기"
T["Casual: Fenster zu"] = "Casual: 창 닫기"
T["Casual: Hinweis"] = "Casual: 알림"
T["Casual: Klick"] = "Casual: 클릭"
T["Casual: Schalter"] = "Casual: 스위치"
T["Charakterstatistik - hoechster Einzelwert, Crit-Status unbekannt"] = "캐릭터 통계 - 최고 단일 수치, 치명타 여부 알 수 없음"
T["Chat-Eingabe und Zauberbefehle koennen beteiligt sein."] = "채팅 입력과 주문 명령이 관련됐을 수 있어요."
T["Chat-Eingabe und Zielwechsel koennen beteiligt sein."] = "채팅 입력과 대상 변경이 관련됐을 수 있어요."
T["Chatnachrichten erfordern in diesem Client eine direkte Eingabe."] = "이 클라이언트에서는 채팅 메시지를 직접 입력해야 해요."
T["Credits"] = "크레딧"
T["Crit-Heilung"] = "치명타 치유"
T["Crit-Import gehoert zu einem anderen Charakter."] = "치명타 가져오기가 다른 캐릭터의 것이에요."
T["Crit-Quelle pruefen"] = "치명타 출처 확인"
T["Crit-Rekorde aus den Kampflog-Dateien uebernommen."] = "치명타 기록을 전투 기록 파일에서 가져왔어요."
T["Crits beim Kampf allein automatisch zaehlen"] = "혼자 싸울 때 치명타 자동 집계"
T["Crits in Gruppe und Dungeon schaetzen"] = "파티와 던전에서 치명타 추정"
T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "창의 X는 Oasis를 바로 접어요. 바의 X는 완전히 닫아요."
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "아이콘의 노란 느낌표가 이것을 알려줘요."
T["Das war nur Glueck! Nochmal!"] = "그건 운이었어! 한 번 더!"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "이게 전부예요. 안내는 설정 > 상태 또는 /oa rundgang으로 언제든 다시 볼 수 있어요."
T["Daten"] = "데이터"
T["Deckend"] = "불투명"
T["Dein Charakter"] = "내 캐릭터"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "내 통계: Oasis 등급, 휘장, 모든 집계"
T["Den Download findest du im Discord der Gilde."] = "다운로드는 길드 Discord에서 찾을 수 있어요."
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "클라이언트가 Oasis의 전투 기록 켜기를 허용하지 않아요 - /combatlog를 직접 입력해 주세요."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "선택한 영역의 내용이에요. 개요에서는 누가 접속 중인지, 예정된 일과 새 소식을 보여줘요."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "미니맵 버튼이나 /oa로 Oasis를 열어요. 오른쪽 위의 선을 누르면 창이 얇은 바로 바뀌어요."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "임원 채널 (/o)과 기록 - 임원 채팅 권한이 있는 등급 전용."
T["Der gelbe Strich links in der Liste zeigt das an."] = "목록 왼쪽의 노란 선이 이것을 알려줘요."
T["Details schliessen"] = "상세 닫기"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "접속 알림에 또렷한 기본음"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "이 클라이언트에서는 캐릭터 통계를 사용할 수 없어요."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "길드 운영진이 내 효과음을 차단했어요."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "바는 접속할 때부터 계속 표시돼요 - 창의 X는 창만 닫아요."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "퍼센트는 총 피해량이 아니라 내 역할 기준 아이템 점수를 비교해요. 효과는 추정치예요."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "통계에서 지금은 읽을 수 있는 값이 없어요."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "우리 길드의 중심이에요. 30초면 익힐 수 있어요 - 중요한 것만 알려드릴게요."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "보호된 기능이 차단됐어요. 정확한 원인은 아직 알 수 없어요."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "맞는 캐릭터 통계를 아직 찾지 못했어요."
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "전체 라이선스 문서는 Oasis 폴더에 있어요: CREDITS.txt, LICENSE, LICENSE-MIT.txt."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "이 길드 등급 (0 = 길드장)이 전리품 위원회에서 투표할 수 있어요."
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "이 캐릭터는 다른 WoW 계정에 있고 나를 본캐로 등록했어요. 확인해야만 길드에서 내 부캐로 인정돼요."
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "이 클라이언트는 애드온 측정값을 제공하지 않아요 (C_AddOnProfiler 없음)."
T["Discord Voice"] = "Discord 음성"
T["Discord Voice: an"] = "Discord 음성: 켬"
T["Discord-Link (kommt in die Nachricht)"] = "Discord 링크 (메시지에 포함돼요)"
T["Discord: %s"] = "Discord: %s"
T["Discord: %s  -  %d im Voice"] = "Discord: %s  -  음성 %d명"
T["Download: %s"] = "다운로드: %s"
T["Drop %s %%"] = "드롭 %s %%"
T["Du nix Kerze nehmen!"] = "양초 못 가져간다!"
T["Du wirst sterben."] = "넌 죽을 거야."
T["Durchsage schreiben"] = "공지 쓰기"
T["Durchsichtig"] = "투명"
T["Echtzeit, aktualisiert jede Sekunde - Oasis und Gildenmodul zusammen"] = "실시간, 1초마다 갱신 - Oasis와 길드 모듈 합산"
T["Eigene Arbeit"] = "자체 제작"
T["Eine Einstellung wurde waehrend einer geschuetzten Aktion geaendert."] = "보호된 동작 중에 설정이 변경됐어요."
T["Eine Nachricht an alle mit Oasis - mit Hinweis und Ton."] = "Oasis 사용자 전원에게 보내는 메시지 - 알림과 소리 포함."
T["Eine Taschenaktion wurde blockiert."] = "가방 동작이 차단됐어요."
T["Eingeklappt"] = "접힘"
T["Einklappen"] = "접기"
T["Einklappen, verschieben, ausblenden"] = "접기, 이동, 숨기기"
T["Einsteiger-Einstellungen gesetzt: ruhigere Hinweise, weniger Seiten. Seiten wieder einblenden unter Einstellungen > Bereiche. Bitte /reload."] = "초보자 설정 적용됨: 더 차분한 알림, 더 적은 페이지. 페이지는 설정 > 영역에서 다시 표시할 수 있어요. /reload 해 주세요."
