T["Quelle: eigene Crits beim Solo-Spiel. In Gruppe und Dungeon meldet WoW Addons nicht, wer getroffen hat."] = "출처: 솔로 플레이 중 내 치명타. 파티와 던전에서는 WoW가 누가 적중했는지 애드온에 알려주지 않아요."
T["Quelle: eigene Crits. Solo sicher erkannt; in Gruppe und Dungeon geschaetzt (Treffer direkt nach dem eigenen Angriff)."] = "출처: 내 치명타. 솔로일 때는 확실히 인식; 파티와 던전에서는 추정 (내 공격 직후의 적중)."
