T["Was die Leitung geaendert hat, Auffaelligkeiten, Daten sichern."] = "운영진이 바꾼 내용, 특이 사항, 데이터 백업."
T["Was du fuer den naechsten Raid noch brauchst - Widerstaende, Verbrauchsgueter, Haltbarkeit, Schluessel"] = "다음 공격대에 아직 필요한 것 - 저항, 소모품, 내구도, 열쇠"
T["Was liegt wo? Suche ueber alle deine Charaktere, ihre Bank und die Gildenbank"] = "무엇이 어디에 있나요? 내 모든 캐릭터, 은행, 길드 은행을 검색"
T["Was moechtest du tun?"] = "무엇을 하고 싶으세요?"
