T["Weitere Gildenevents folgen hier."] = "다른 길드 이벤트가 여기에 이어져요."
T["Weitere Plaetze fuellen sich, sobald mehr Gildenmitglieder mit Oasis gekaempft haben."] = "Oasis를 쓰는 길드원이 더 많이 싸우면 나머지 순위가 채워져요."
T["Weitere Upgrades in diesem Dungeon"] = "이 던전의 다른 업그레이드"
T["Welche Seiten sieht die Gilde - und ab welchem Rang."] = "길드가 볼 페이지 - 그리고 최소 등급."
T["Welcher Rang darf Durchsagen, Termine, Bank und mehr."] = "어느 등급이 공지, 일정, 은행 등을 쓸 수 있는지."
T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "그날 이미 필요로 아이템을 받은 사람은 필요 굴림에서 아이템이 없는 모두의 뒤로 밀려요 (같은 굴림 순위)."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "일정에 아이템을 예약한 사람은 필요 굴림에서 다른 모두보다 앞서요."
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "파티나 공격대에서 누가 어떤 버프를 가졌는지 - 그리고 부족한 버프를 누가 줄 수 있는지"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "누가 길드에 있는지, 어떤 등급인지, 누가 구버전 Oasis인지."
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "누가 오래 접속하지 않았는지 - 클릭 한 번으로 정리."
T["Wie die Schrift"] = "글꼴과 같게"
T["Wieder am Talentfenster andocken"] = "특성 창에 다시 붙이기"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "파티에서는 WoW가 누가 적중했는지 애드온에 알려주지 않아요. Oasis는 내 공격 바로 뒤에 이어지고 전투 후 피해량 미터기와 맞는 치명타만 집계해요. 순위에 추정으로 표시돼요."
T["WoW-Klassiker"] = "WoW 클래식 명곡"
T["Wochenaufgaben %d/%d"] = "주간 과제 %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft 및 관련 이름, 문장, 그래픽은 Blizzard Entertainment의 상표예요. Oasis는 팬 프로젝트이며 Blizzard와 관련이 없어요."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "주사위: 필요 > 부특성 > 형상변환 순서, 그다음 굴림. 점수: 전리품 점수의 우선순위로 결정. 전리품 위원회: 임원이 투표하고 전리품 담당자가 지급."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "톱니바퀴 = 설정 (외관, 소리, 알림). 그 옆에 언어와 - 길드 운영진에게는 - 왕관."
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "녹색, 파란색, 영웅 아이템에서 마력 추출로 나올 수 있는 재료를 보여줘요"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "목록에 음성으로 대화한다고 표시해요 (Discord 등). 참가는 계속 Blizzard 또는 파티장이 처리해요."
T["Zeigt nur Mains. Twinks sind Charaktere, die einem anderen Main zugeordnet sind."] = "본캐만 보여줘요. 부캐는 다른 본캐에 연결된 캐릭터예요."
T["Zeigt nur die Kopfzeile mit der Anzahl der Builds."] = "빌드 개수가 있는 머리줄만 보여줘요."
T["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "길드에서 누가 같은 퀘스트를 가지고 있고 지금 접속 중인지 바로 보여줘요 - 클릭 한 번으로 초대."
T["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "누군가 공략이 있는 보스를 대상으로 잡으면 짧은 알림이 표시돼요 (전투 중 제외)."
